# ── ProductCard ──
cat > app/components/ProductCard.tsx << 'EOF'
'use client';
import Link from 'next/link';
import { Product, formatPrice, buildWhatsAppLink, categoryConfig } from '../data/products';
import CategoryChip from './CategoryChip';

export default function ProductCard({ product }: { product: Product }) {
  const cfg = categoryConfig[product.category];
  const initials = product.name.split(' ').filter(w => w.length > 1).slice(0, 2).map(w => w[0]).join('');
  return (
    <article className="group bg-white rounded-2xl border border-[var(--color-border)] overflow-hidden hover:shadow-lg hover:-translate-y-0.5 transition-all duration-300">
      <Link href={`/products/${product.slug}`}>
        <div className={`w-full aspect-square flex flex-col items-center justify-center gap-3 ${cfg?.bg ?? 'bg-[var(--color-surface)]'}`}>
          <span className="text-5xl">{cfg?.emoji ?? '📦'}</span>
          <span className={`text-sm font-semibold tracking-wider uppercase ${cfg?.color ?? 'text-[var(--color-text-secondary)]'}`}>{initials}</span>
        </div>
      </Link>
      <div className="p-4 flex flex-col gap-3">
        <div className="flex items-start justify-between gap-2">
          <Link href={`/products/${product.slug}`}>
            <h3 className="font-semibold text-[var(--color-text)] leading-snug group-hover:text-[var(--color-accent)] transition-colors line-clamp-2">{product.name}</h3>
          </Link>
          <CategoryChip category={product.category} />
        </div>
        <p className="text-lg font-bold text-[var(--color-text)] tabular-nums">{formatPrice(product.price)}</p>
        <a href={buildWhatsAppLink(product.name, product.price)} target="_blank" rel="noopener noreferrer"
          className="flex items-center justify-center gap-2 w-full py-2.5 rounded-full bg-[#25d366] text-white text-sm font-semibold hover:bg-[#22c55e] transition-colors">
          Order on WhatsApp
        </a>
      </div>
    </article>
  );
}
EOF

# ── WhatsAppButton ──
cat > app/components/WhatsAppButton.tsx << 'EOF'
'use client';
interface Props { productName?: string; price?: number; label?: string; size?: 'sm' | 'md' | 'lg'; className?: string; }
function formatNPR(price: number) {
  const s = price.toString(); const last3 = s.slice(-3); const rest = s.slice(0, -3);
  return `NPR ${rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',')},${last3}`;
}
export default function WhatsAppButton({ productName, price, label, size = 'md', className = '' }: Props) {
  const msg = productName && price !== undefined ? `Hi, I want to order ${productName} - ${formatNPR(price)}` : 'Hi, I want to browse your products';
  const sizes = { sm: 'text-sm px-4 py-2', md: 'text-sm px-5 py-2.5', lg: 'text-base px-7 py-3.5' };
  return (
    <a href={`https://wa.me/9779800000000?text=${encodeURIComponent(msg)}`} target="_blank" rel="noopener noreferrer"
      className={`inline-flex items-center justify-center gap-2 font-semibold rounded-full bg-[#25d366] text-white hover:bg-[#22c55e] transition-colors ${sizes[size]} ${className}`}>
      {label ?? 'Order via WhatsApp'}
    </a>
  );
}
EOF

